            b2cs: {
                /** @example 27-Maharashtra */
                placeOfSupply: string;
                /** @example 1800 */
                rateBps: number;
                taxablePaise: components["schemas"]["Money"];
                igstPaise: components["schemas"]["Money"];
                cgstPaise: components["schemas"]["Money"];
                sgstPaise: components["schemas"]["Money"];
                orders: number;
            }[];
            /** @description Table 12 - HSN summary of goods (shipping and COD fees are not listed here). `hsn` is `NOT SET` when the variant has no HSN code. */
